{"task": "Allocate all 400 tickets exactly once, with no duplicates or missing values. Synchronize allocation and concurrent count readers; retain every scheduling hook.", "editable_files": ["solution.c"], "sources": {"solution.c": "#include "state.h"
#include <sched.h>
int reserve_ticket(TicketOffice *office) {
    int ticket = office->next_ticket;
    sched_yield();
    office->next_ticket = ticket + 1;
    return ticket;
}
int issued_count(TicketOffice *office) {
    return office->next_ticket;
}
"}, "headers": {"state.h": "#ifndef STATE_H
